178	export function useCreateMemo() {
179	  const queryClient = useQueryClient();
180	
181	  return useMutation({
182	    mutationFn: async (memoToCreate: Memo) => {
183	      const memo = await memoServiceClient.createMemo({ memo: memoToCreate });
184	      return memo;
185	    },
186	    onSuccess: (newMemo) => {
187	      // Invalidate memo lists to refetch
188	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
189	      // Add new memo to cache
190	      queryClient.setQueryData(memoKeys.detail(newMemo.name), newMemo);
191	      // Invalidate user stats
192	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
193	    },
194	  });
195	}
