34	export const useMemoFilters = (options: UseMemoFiltersOptions = {}): string | undefined => {
35	  const { creatorName, includeShortcuts = false, includePinned = false, visibilities } = options;
36	
37	  const { shortcuts } = useAuth();
38	  const { filters, shortcut: currentShortcut } = useMemoFilterContext();
39	
40	  // Get selected shortcut if needed
41	  const selectedShortcut = useMemo(() => {
42	    if (!includeShortcuts) return undefined;
43	    return shortcuts.find((shortcut) => getShortcutId(shortcut.name) === currentShortcut);
44	  }, [includeShortcuts, currentShortcut, shortcuts]);
45	
46	  // Build filter
47	  return useMemo(() => {
48	    const conditions: string[] = [];
49	
50	    // Add creator filter if provided
51	    if (creatorName) {
52	      const creatorFilter = buildMemoCreatorFilter(creatorName);
53	      if (creatorFilter) {
54	        conditions.push(creatorFilter);
55	      }
56	    }
57	
58	    // Add shortcut filter if enabled and selected
59	    if (includeShortcuts && selectedShortcut?.filter) {
60	      conditions.push(selectedShortcut.filter);
61	    }
62	
63	    // Add active filters from context
64	    for (const filter of filters) {
65	      if (filter.factor === "contentSearch") {
66	        conditions.push(`content.contains(${escapeFilterValue(filter.value)})`);
67	      } else if (filter.factor === "tagSearch") {
68	        conditions.push(`tag in [${escapeFilterValue(filter.value)}]`);
69	      } else if (filter.factor === "pinned") {
70	        if (includePinned) {
71	          conditions.push(`pinned`);
72	        }
73	      } else if (filter.factor === "property.hasLink") {
74	        conditions.push(`has_link`);
75	      } else if (filter.factor === "property.hasTaskList") {
76	        conditions.push(`has_task_list`);
77	      } else if (filter.factor === "property.hasCode") {
78	        conditions.push(`has_code`);
79	      } else if (filter.factor === "displayTime") {
80	        const filterDate = new Date(filter.value);
81	        const filterUtcTimestamp = filterDate.getTime() + filterDate.getTimezoneOffset() * 60 * 1000;
82	        const startTimestamp = Math.floor(filterUtcTimestamp / 1000);
83	        const endTimestamp = startTimestamp + 60 * 60 * 24;
84	
85	        conditions.push(`created_ts >= timestamp(${startTimestamp}) && created_ts < timestamp(${endTimestamp})`);
86	      }
87	    }
88	
89	    // Add visibility filter if specified
90	    if (visibilities && visibilities.length > 0) {
91	      const visibilityValues = visibilities.map((v) => `"${getVisibilityName(v)}"`).join(", ");
92	      conditions.push(`visibility in [${visibilityValues}]`);
93	    }
94	
95	    return conditions.length > 0 ? conditions.join(" && ") : undefined;
96	  }, [creatorName, includeShortcuts, includePinned, visibilities, selectedShortcut, filters]);
